const fs=require('fs'),path=require('path'),crypto=require('crypto');
const {chromium}=require('/Users/vibhusapra/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
(async()=>{
 const root=process.cwd(),base=path.join(root,'.artifacts/personal-sync-v1/landscape-qa-v2');fs.mkdirSync(base,{mode:0o700});
 const sha=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
 const files=['docs/landscape.html','docs/landscape.json','docs/features.json','scripts/research-report.py','benchmarks/screenpipe-keyword-http-v1.json','benchmarks/vault-collector-trace-v1.json','benchmarks/personal-sync-foundation-v1.json','.artifacts/personal-sync-v1/qa-landscape-v2.cjs'];const frozen=Object.fromEntries(files.map(f=>[f,sha(f)]));
 const browser=await chromium.launch({headless:true,executablePath:'/Users/vibhusapra/Library/Caches/ms-playwright/chromium_headless_shell-1248/chrome-headless-shell-mac-arm64/chrome-headless-shell'});
 const context=await browser.newContext({viewport:{width:1440,height:960}});
 await context.addInitScript(()=>{Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async text=>{window.__ownedCopiedText=text}}})});
 const page=await context.newPage(),requests=[],errors=[];page.on('request',r=>requests.push(r.url()));page.on('pageerror',e=>errors.push(String(e)));
 const report={format:'OSwind comparison browser QA',state:'running',browserVersion:browser.version(),frozen,scope:'Own file:// artifact in an isolated headless browser. Clipboard adapter stubbed; no user clipboard, authenticated page, network request, native app/TCC or competitor runtime.',screenshots:[]};
 try {
  await page.goto('file://'+path.join(root,'docs/landscape.html'));
  if(await page.locator('article.vendor').count()!==20||await page.locator('#rows tr').count()!==78)throw Error('Catalog count');
  await page.screenshot({path:path.join(base,'desktop-top.png')});report.screenshots.push('desktop-top.png');
  await page.locator('article.vendor').nth(16).scrollIntoViewIfNeeded();await page.screenshot({path:path.join(base,'desktop-new-profiles.png')});report.screenshots.push('desktop-new-profiles.png');
  const bench=JSON.parse(fs.readFileSync(path.join(root,'benchmarks/screenpipe-keyword-http-v1.json'),'utf8'));const actual=await page.locator('#screenpipe-http tbody tr').allTextContents();const expected=bench.runs.flatMap(r=>['screenpipe','oswind'].map(k=>r.records.toLocaleString('en-US')+(k==='screenpipe'?'Screenpipe 0.4.53':'OSwind a5d4af4')+r.summary[k].medianMS.toFixed(3)+' ms'+r.summary[k].p95MS.toFixed(3)+' ms'+r.summary[k].exactSets+'/'+r.summary[k].observations));if(JSON.stringify(actual)!==JSON.stringify(expected))throw Error('Measured benchmark cells differ from receipt');await page.locator('#screenpipe-http').scrollIntoViewIfNeeded();await page.screenshot({path:path.join(base,'desktop-component-benchmark.png')});report.screenshots.push('desktop-component-benchmark.png');await page.locator('#filter').fill('Real competitor benchmarks');if(await page.locator('#rows tr:visible td').first().textContent()!=='F071'||await page.locator('#rows tr:visible').getAttribute('data-status')!=='partial')throw Error('F071 status');await page.locator('#filter').fill('Encrypted vault / biometric unlock');if(await page.locator('#rows tr:visible td').first().textContent()!=='F048'||!(await page.locator('#rows tr:visible').textContent()).includes('cf174b3'))throw Error('Collector evidence missing');await page.locator('#filter').fill('Personal device sync');if(await page.locator('#rows tr:visible td').first().textContent()!=='F059'||await page.locator('#rows tr:visible').getAttribute('data-status')!=='todo'||!(await page.locator('#rows tr:visible').textContent()).includes('46'))throw Error('Sync TODO/evidence boundary');await page.locator('#filter').fill('Sampled text observation spans');if(await page.locator('#rows tr:visible').count()!==1||await page.locator('#rows tr:visible td').first().textContent()!=='F078')throw Error('Span filter');
  await page.locator('#filter').fill('Standalone Accessibility-only');if(await page.locator('#rows tr:visible').count()!==1)throw Error('AX filter');
  if(await page.locator('#rows tr:visible td').first().textContent()!=='F077')throw Error('AX ID');
  await page.locator('#status').selectOption('todo');if(await page.locator('#rows tr:visible').count()!==0)throw Error('Intersection filter');
  await page.locator('#filter').fill('');if(await page.locator('#rows tr:visible').count()!==3)throw Error('TODO count');
  await page.locator('#copy').click();const copied=await page.evaluate(()=>window.__ownedCopiedText);
  if(copied.split('\n').length!==3||!copied.startsWith('- [ ] F013')||copied.includes('F071'))throw Error('Multiline copied TODOs');
  await page.locator('#status').selectOption('');if(await page.locator('#copy').textContent()!=='Copy visible TODOs as Markdown')throw Error('Stale copy label');
  await page.locator('#status').selectOption('out of v0 desktop scope');await page.locator('#copy').click();if(await page.evaluate(()=>window.__ownedCopiedText)!=='')throw Error('Outside-scope tasks copied');
  await page.locator('#status').selectOption('');
  await page.setViewportSize({width:390,height:844});await page.evaluate(()=>scrollTo(0,0));await page.screenshot({path:path.join(base,'mobile-top.png')});report.screenshots.push('mobile-top.png');
  await page.locator('article.vendor').nth(19).scrollIntoViewIfNeeded();await page.screenshot({path:path.join(base,'mobile-goldfish.png')});report.screenshots.push('mobile-goldfish.png');
  await page.locator('#filter').fill('Accessibility-only');await page.locator('#filter').scrollIntoViewIfNeeded();await page.screenshot({path:path.join(base,'mobile-ledger.png')});report.screenshots.push('mobile-ledger.png');
  const sizes=await page.evaluate(()=>({viewport:innerWidth,document:document.documentElement.scrollWidth,tableViewport:document.querySelector('#parity .table-wrap').clientWidth,tableContent:document.querySelector('#parity .table-wrap').scrollWidth}));
  if(sizes.document>sizes.viewport||sizes.tableContent<=sizes.tableViewport)throw Error('Narrow overflow containment');
  if(errors.length||requests.some(u=>!u.startsWith('file:')))throw Error('JS error or network asset');
  const noJS=await browser.newContext({javaScriptEnabled:false,viewport:{width:390,height:844}}),plain=await noJS.newPage();await plain.goto('file://'+path.join(root,'docs/landscape.html'));if(await plain.locator('article.vendor').count()!==20||await plain.locator('#rows tr:visible').count()!==78)throw Error('No-JS content');await noJS.close();
  if(files.some(f=>sha(f)!==frozen[f]))throw Error('QA inputs changed');
  Object.assign(report,{state:'completed',vendors:20,requirements:78,viewportSizes:sizes,filterAndIntersectionPass:true,benchmarkCellsMatchReceipt:true,copyThreeMultilineTODOs:true,copyLabelResets:true,outsideScopeExcludedFromCopy:true,withoutJavaScriptUsable:true,networkRequests:0,pageErrors:errors});
 } catch(error){report.state='failed';report.error=String(error);throw error}
 finally{report.screenshots=report.screenshots.map(f=>({path:f,sha256:sha(path.join(base,f))}));fs.writeFileSync(path.join(base,'report.json'),JSON.stringify(report,null,2)+'\n');await browser.close()}
 console.log(JSON.stringify({state:report.state,vendors:report.vendors,requirements:report.requirements,viewportSizes:report.viewportSizes},null,2));
})().catch(e=>{console.error(e);process.exitCode=1});
